// === Tab: VoronoiGenerator ===
// ########################################################## //
// #                                                        # //
// #            A Revision of my tileable voronoi           # //
// #              pattern generator that uses a             # // 
// #           WEBGL shader to generate the pattern         # //
// #          on the GPUmuch faster than my previous        # //
// #                   could do on the CPU                  # //
// #                                                        # //
// ########################################################## //
// #                                                        # //
// #                Written by Fabian Kober                 # //
// #                  fabian-kober@gmx.net                  # //
// #                                                        # //
// ########################################################## //

// the amount of cells to generate
let numOfCells = 99;
// factor for the brighntess of the pattern
let brightnessFactor = 7;

// use gaussian ditribution to seed the cells
let useRandomGaussian = false;

// the means for x and y if using gaussian
let gaussianMeanX;
let gaussianMeanY;

// standard deviaton for x and y if using gaussian
let gaussianSdX;
let gaussianSdY;

// menu to change a bunch of values
let menu;

// the shader to do the work for us
let sh;

function setup() {
    // setup canvas
    createCanvas(1920, 1080, WEBGL);
		background(0);

    // create the shader
    sh = createShader(vert, frag);

    // setup gaussian values
    gaussianMeanX = 0.5;
    gaussianMeanY = 0.5;
    gaussianSdX = 0.25;
    gaussianSdY = 0.25;

    // create menu and hide it
    menu = new Menu(10, 10);
    menu.toggle();

    // generate
    generateVoronoi();
}

// generates a voronoi pattern
function generateVoronoi() {
    let startTime = millis();
    // first we need to create a bunch of points as "seeds" for our cells
    let pointsX = [];
    let pointsY = [];
    for (let i = 0; i < numOfCells; ++i) {
        let pointX;
        let pointY;
        // choose the position of the point either by using gaussian distribution to get more (ergo smaller) cells at a defined point or by using standart noise
        if (useRandomGaussian) {
            pointX = randomGaussian(gaussianMeanX, gaussianSdX);
            pointY = randomGaussian(gaussianMeanY, gaussianSdY);
        } else {
            pointX = random(1.0);
            pointY = random(1.0);
        }

        // save the point
        pointsX.push(pointX);
        pointsY.push(pointY);
    }

    // activate the shader and set all needed uniforms
    shader(sh);
    sh.setUniform('u_pointsX', pointsX);
    sh.setUniform('u_pointsY', pointsY);
    sh.setUniform('u_numOfPoints', pointsX.length);
    sh.setUniform('u_brightnesFactor', brightnessFactor);

    // draw a quad using the shader
    quad(-1,-1, -1, 1, 1, 1, 1, -1);
}

// handle key presses
function keyPressed() {
    switch (key) {
        case ' ':
            menu.toggle();
            break;

        case 's':
        case 'S':
            // for some reason the file name is messed up on OpenProcessing, this works locally but not on here. It saves the image though, it just has a weird name
            saveCanvas('Voronoi.png', 'png');
            break;
    }
}

// === Tab: Menu ===
// container for the menu of the Voronoi pattern generator
class Menu {
    // creates the menu at the provided position
    constructor(x, y) {
        this.x = x;
        this.y = y;

        // spacing between the elements
        this.spacing = 5;

        // flag whether the menu is hidded atm
        this.hidden = false;

        // start y pos
        let elemY = y;

        // Label for Cell Number input field
        this.cellInputLabel = createDiv("Cells:");
        this.cellInputLabel.position(x, elemY);
        elemY += this.distToNextY(this.cellInputLabel);

        // cell input field
        this.cellInput = createInput(numOfCells, 'number');
        this.cellInput.position(x, elemY);
        this.cellInput.changed(value => numOfCells = value.srcElement.valueAsNumber);
        elemY += this.distToNextY(this.cellInput);

        // Label for brightness value input field
        this.brighnesstInputLabel = createDiv("Brighness:");
        this.brighnesstInputLabel.position(x, elemY);
        elemY += this.distToNextY(this.brighnesstInputLabel);

        // brightness Input field
        this.brightnessInput = createInput(brightnessFactor, 'number');
        this.brightnessInput.position(x, elemY);
        this.brightnessInput.changed(value => brightnessFactor = value.srcElement.valueAsNumber);
        elemY += this.distToNextY(this.brightnessInput);

        // toggle for using Gaussian Distribution
        this.useGausToggle = createCheckbox("Use Gaussian Distribution", useRandomGaussian);
        this.useGausToggle.position(x, elemY);
        this.useGausToggle.changed(() => {
            useRandomGaussian = !useRandomGaussian;
            if (useRandomGaussian)
                this.showGaus();
            else
                this.hideGaus();
        });
        elemY += this.distToNextY(this.useGausToggle);

        // save current Y position for generate button when no gaussion distribution should be used
        this.generateButtonYPosNormal = elemY;

        // Label for Gaus X Mean
        this.gausXMeanLabel = createDiv("Mean X:");
        this.gausXMeanLabel.position(x, elemY);
        elemY += this.distToNextY(this.gausXMeanLabel);

        // input field for Gaus X Mean
        this.gausXMeanInput = createInput(gaussianMeanX, 'number');
        this.gausXMeanInput.position(x, elemY);
        this.gausXMeanInput.changed(value => gaussianMeanX = value.srcElement.valueAsNumber);
        elemY += this.distToNextY(this.gausXMeanInput);

        // Label for Gaus Y Mean
        this.gausYMeanLabel = createDiv("Mean Y:");
        this.gausYMeanLabel.position(x, elemY);
        elemY += this.distToNextY(this.gausYMeanLabel);

        // input field for Gaus Y Mean
        this.gausYMeanInput = createInput(gaussianMeanY, 'number');
        this.gausYMeanInput.position(x, elemY);
        this.gausYMeanInput.changed(value => gaussianMeanY = value.srcElement.valueAsNumber);
        elemY += this.distToNextY(this.gausYMeanInput);

        // Label for Standard Deviation X
        this.gausXSdLabel = createDiv("Standard Deviation X:");
        this.gausXSdLabel.position(x, elemY);
        elemY += this.distToNextY(this.gausXSdLabel);

        // input field for Standard Deviation X
        this.gausXSdInput = createInput(gaussianSdX, 'number');
        this.gausXSdInput.position(x, elemY);
        this.gausXSdInput.changed(value => gaussianSdX = value.srcElement.valueAsNumber);
        elemY += this.distToNextY(this.gausXSdInput);

        // Label for Standard Deviation Y
        this.gausYSdLabel = createDiv("Standard Deviation Y:");
        this.gausYSdLabel.position(x, elemY);
        elemY += this.distToNextY(this.gausYSdLabel);

        // input field for Standard Deviation Y
        this.gausYSdInput = createInput(gaussianSdY, 'number');
        this.gausYSdInput.position(x, elemY);
        this.gausYSdInput.changed(value => gaussianSdY = value.srcElement.valueAsNumber);
        elemY += this.distToNextY(this.gausYSdInput);

        // save current y pos for generation button when using Gaus
        this.generateButtonYPosGaus = elemY;

        // Button to start generation
        this.generateButton = createButton("Generate Voronoi");
        this.generateButton.position(x, useRandomGaussian ? this.generateButtonYPosGaus : this.generateButtonYPosNormal);
        this.generateButton.mouseClicked(() => {
            this.toggle();
            generateVoronoi();
        });

        // hide gaus option if needed
        if (!useRandomGaussian)
            this.hideGaus();
    }

    // gets the difference to the next y position
    distToNextY(element) {
        return element.size().height + this.spacing;
    }

    hideGaus() {
        this.gausXMeanLabel.hide();
        this.gausXMeanInput.hide();
        this.gausYMeanLabel.hide();
        this.gausYMeanInput.hide();
        this.gausXSdLabel.hide();
        this.gausXSdInput.hide();
        this.gausYSdLabel.hide();
        this.gausYSdInput.hide();

        this.generateButton.position(this.x, this.generateButtonYPosNormal);
    }

    showGaus() {
        this.gausXMeanLabel.show();
        this.gausXMeanInput.show();
        this.gausYMeanLabel.show();
        this.gausYMeanInput.show();
        this.gausXSdLabel.show();
        this.gausXSdInput.show();
        this.gausYSdLabel.show();
        this.gausYSdInput.show();

        this.generateButton.position(this.x, this.generateButtonYPosGaus);
    }

    toggle() {
        if (this.hidden) {
            if (useRandomGaussian)
                this.showGaus();

            this.cellInputLabel.show();
            this.cellInput.show();
            this.brighnesstInputLabel.show();
            this.brightnessInput.show();
            this.useGausToggle.show();
            this.generateButton.show();
        } else {
            this.hideGaus();

            this.cellInputLabel.hide();
            this.cellInput.hide();
            this.brighnesstInputLabel.hide();
            this.brightnessInput.hide();
            this.useGausToggle.hide();
            this.generateButton.hide();
        }

        this.hidden = !this.hidden;
    }
}

// === Tab: Shader ===
let vert = `
attribute vec4 aPosition;

varying vec2 v_uv;

void main() {
    // calculate uvs
    v_uv = aPosition.xy;
    v_uv.y *= -1.0;
    v_uv.x = v_uv.x * 0.5 + 0.5;
    v_uv.y = v_uv.y * 0.5 + 0.5; 

    // set position
    gl_Position = aPosition;
}
`;

let frag = `
precision mediump float;

// our points. We can't have much more than 500 because a WEBGL shader can't have more than 1024 uniforms and each array entry counts as one uniform.
// I also can't use vec2 beacuse p5js' setUniform method does not seem to work correctly with arrays of vectors
uniform float u_pointsX[500];
uniform float u_pointsY[500];

// the actual number of points because the arrays have to have fixed sizes
uniform int u_numOfPoints;

// brightnes for the voronoi pattern
uniform float u_brightnesFactor;

// uv coordinates
varying vec2 v_uv;

void main() {
     // calculate the distance to the closest point
     float closestDist = 10.0;
     for (int i = 0; i < 500; ++i) {
        // WEBGL does not support for loops with variable expressions, so we have to bail out manually
        if(i >= u_numOfPoints)
            break;

         // get the point and all its tiled variants
         vec2 point = vec2(u_pointsX[i], u_pointsY[i]);
         vec2 pointUp = vec2(u_pointsX[i], u_pointsY[i]-1.0);
         vec2 pointDown = vec2(u_pointsX[i], u_pointsY[i]+1.0);
         vec2 pointLeft = vec2(u_pointsX[i]-1.0, u_pointsY[i]);
         vec2 pointRight = vec2(u_pointsX[i]+1.0, u_pointsY[i]);

         // calculate the vector between this pixel and the tiled point
         vec2 diff = point-v_uv;
         vec2 diffUp = pointUp-v_uv;
         vec2 diffDown = pointDown-v_uv;
         vec2 diffLeft = pointLeft-v_uv;
         vec2 diffRight = pointRight-v_uv;

         // get the length of all the vectors
         float d = length(diff);
         float dUp = length(diffUp);
         float dDown = length(diffDown);
         float dLeft = length(diffLeft);
         float dRight = length(diffRight);

         // get the closest distance
         closestDist = min(closestDist,min(d, min(dUp, min(dDown, min(dLeft, dRight)))));
     }


    // calculate a brightness from the distance value and set it as the pixel color
    float brightness = closestDist * u_brightnesFactor;
    gl_FragColor = vec4(brightness/3.0, brightness, brightness/2.0, 1.0);
}
`;

